def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    opp_x, opp_y = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    if resources:
        target = min(resources, key=lambda r: dist((x,y), r))
    else:
        target = (opp_x, opp_y)
    dx = dy = 0
    if target:
        if target[0] > x: dx = 1
        elif target[0] < x: dx = -1
        if target[1] > y: dy = 1
        elif target[1] < y: dy = -1
    next_x, next_y = x + dx, y + dy
    if (next_x, next_y) in obstacles or not (0 <= next_x < width and 0 <= next_y < height):
        if dx != 0:
            alt_x = x
            alt_y = y + 1 if y + 1 < height and (x, y + 1) not in obstacles else y -1
            if 0 <= alt_y < height and (x, alt_y) not in obstacles:
                dy = alt_y - y
        elif dy != 0:
            alt_x = x + 1 if x + 1 < width and (x + 1, y) not in obstacles else x -1
            if 0 <= alt_x < width and (alt_x, y) not in obstacles:
                dx = alt_x - x
    return [dx, dy]
